package com.nigson.experience.consent;
import java.util.*;
import com.nigson.shared.problem.*;
import tools.jackson.databind.JsonNode;
public final class PhoneValues {
 private PhoneValues(){}
 public static final Set<String> CHANNELS=Set.of("SMS","WHATSAPP"),PHONE_PURPOSES=Set.of("ORDER_UPDATES","MARKETING","CART_RECOVERY"),PURPOSES=Set.of("NEWSLETTER","ORDER_UPDATES","MARKETING","CART_RECOVERY");
 public static String phone(String value){if(value==null||!value.matches("\\+234[1-9][0-9]{9}"))throw ApiValues.invalid();return value;}
 public record Input(String channel,String address,String policyVersion,Set<String> consentedPurposes){public Input{if(!CHANNELS.contains(channel==null?"":channel)||policyVersion==null||!policyVersion.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,39}")||consentedPurposes==null||consentedPurposes.isEmpty()||!PHONE_PURPOSES.containsAll(consentedPurposes))throw ApiValues.invalid();address=phone(address);consentedPurposes=Set.copyOf(consentedPurposes);}@Override public String toString(){return "PhoneInput[protected]";}}
 public record Destination(UUID id,String channel,String maskedAddress,String status,long version){}
 public record Context(String phone,String channel,String code,java.time.Instant expiresAt,String templateCode){@Override public String toString(){return "PhoneContext[protected]";}}
 public static Input input(JsonNode node){if(node==null||!node.isObject()||!node.propertyNames().equals(Set.of("channel","address","policyVersion","consentedPurposes")))throw ApiValues.invalid();for(String name:List.of("channel","address","policyVersion"))if(!node.path(name).isString())throw ApiValues.invalid();var values=node.path("consentedPurposes");if(!values.isArray()||values.isEmpty()||values.size()>3)throw ApiValues.invalid();var purposes=new HashSet<String>();for(var v:values)if(!v.isString()||!purposes.add(v.asString()))throw ApiValues.invalid();return new Input(node.path("channel").asString(),node.path("address").asString(),node.path("policyVersion").asString(),purposes);}
 public static Problem.Failure denied(){return new Problem.Failure(ProblemCode.CONSENT_RULE_VIOLATION);}
 public record Eligibility(boolean eligible,String reasonCode,String email,String phone,String destinationHash,String policyRevision){@Override public String toString(){return "PhoneEligibility[protected]";}}
 public record EligibilityInput(UUID partyId,UUID destinationId,String emailHash,String channel,String purpose){public EligibilityInput(UUID partyId,UUID destinationId,String channel,String purpose){this(partyId,destinationId,null,channel,purpose);}public EligibilityInput{boolean email="EMAIL".equals(channel);if(partyId==null&&destinationId==null&&emailHash==null||partyId!=null&&partyId.equals(new UUID(0,0))||destinationId!=null&&destinationId.equals(new UUID(0,0))||emailHash!=null&&!emailHash.matches("[a-f0-9]{64}")||!(email||CHANNELS.contains(channel==null?"":channel))||!(email?Set.of("NEWSLETTER","MARKETING","CART_RECOVERY","ORDER_UPDATES"):PURPOSES).contains(purpose==null?"":purpose))throw ApiValues.invalid();if(!email&&emailHash!=null)throw ApiValues.invalid();}}
 public static EligibilityInput eligibility(JsonNode node){if(node==null||!node.isObject()||!Set.of("partyId","destinationId","emailHash","channel","purpose").containsAll(node.propertyNames())||!node.path("channel").isString()||!node.path("purpose").isString())throw ApiValues.invalid();for(String name:List.of("partyId","destinationId","emailHash"))if(node.has(name)&&!node.path(name).isString())throw ApiValues.invalid();return new EligibilityInput(node.has("partyId")?ApiValues.uuid(node.path("partyId").asString()):null,node.has("destinationId")?ApiValues.uuid(node.path("destinationId").asString()):null,node.has("emailHash")?node.path("emailHash").asString():null,node.path("channel").asString(),node.path("purpose").asString());}
 public record Signal(UUID commandId,String destinationHash,String channel,String reason){public Signal{if(commandId==null||commandId.equals(new UUID(0,0))||destinationHash==null||!destinationHash.matches("[a-f0-9]{64}")||!CHANNELS.contains(channel==null?"":channel)||!Set.of("HARD_BOUNCE","COMPLAINT","OPT_OUT").contains(reason==null?"":reason))throw ApiValues.invalid();}}
 public static Signal signal(JsonNode node){if(node==null||!node.isObject()||!node.propertyNames().equals(Set.of("commandId","destinationHash","channel","reason")))throw ApiValues.invalid();for(String name:node.propertyNames())if(!node.path(name).isString())throw ApiValues.invalid();return new Signal(ApiValues.uuid(node.path("commandId").asString()),node.path("destinationHash").asString(),node.path("channel").asString(),node.path("reason").asString());}
}
